'use strict';

/**
 * Game service — session lifecycle and scoring for Space Fractions.
 *
 * Responsibilities (space-fractions.md lines 17-24, 47-50; Architecture_View
 * Lines 79-145 ProcessView):
 *   - Create a game from the question pool (or an explicit questionIds list for
 *     reproducible practice). Never expose `correctAnswer` to players.
 *   - Fetch game state, pause/resume, submit answers, and read the score.
 *   - Owner authorization: a game may only be read/mutated by its owner
 *     (other users -> 403 or 404).
 *   - Per-game serialization of scoring and transactional deduplication: the
 *     UNIQUE (game_id, question_id) constraint prevents a repeat answer from
 *     incrementing the score.
 *   - Answering while paused -> 409. Answering a repeated question -> 409 (or
 *     idempotent 200; this implementation uses 409 for repeat).
 *
 * The service depends on three injectable collaborators so the default
 * `npm test` runs without PostgreSQL, Redis or an identity provider:
 *   - repository:       game persistence (see ./repository.js)
 *   - questionProvider: source of question records for new games
 *   - eventPublisher:   emits score events (see ./events.js, RabbitMQ)
 *   - verifier:         OIDC token verifier (shared src/shared/oidc.js)
 *   - userRepository:   sub -> numeric owner id mapping (user-service contract)
 *
 * All owner authorization is performed against the numeric internal user id
 * derived from the verified OIDC `sub`, matching the user-service's mapping
 * contract (space-fractions.md line 48).
 */

const express = require('express');
const { Client } = require('pg');

const oidc = require('../../../src/shared/oidc');
const { validateAnswer } = require('../../../src/shared/fraction');

const PORT = Number(process.env.GAME_SERVICE_PORT || process.env.PORT || 3001);

/** Ownership/authorization error (other user's game -> 403/404). */
class GameServiceError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'GameServiceError';
    this.status = status;
  }
}

/** Domain state names as stored in the `games.state` column. */
const GAME_STATE = {
  IN_PROGRESS: 'in_progress',
  PAUSED: 'paused',
  FINISHED: 'finished',
};

/**
 * Resolve the numeric owner id from an Authorization header, reusing the
 * user-service mapping contract (sub -> users.id) via an injected repository.
 *
 * @param {object} userRepository { findBySubject }
 * @param {object} verifier       { verify(token): Promise<payload> }
 * @param {string} [authorizationHeader]
 * @returns {Promise<number>} numeric internal user id
 * @throws {oidc.AuthError} missing/invalid credentials -> HTTP 401
 */
async function resolveOwner(userRepository, verifier, authorizationHeader, profile) {
  const token = oidc.bearerToken(authorizationHeader);
  const payload = await verifier.verify(token);
  const sub = payload.sub;
  const existing = await userRepository.findBySubject(sub);
  const user =
    existing ||
    (await userRepository.findOrCreateBySubject(
      sub,
      profile || payload.preferred_username || sub,
    ));
  return user.id;
}

/**
 * Strip `correctAnswer` from question records for player-facing responses.
 * The provider may return full records including correctAnswer (needed for
 * scoring); players must never receive it.
 */
function toPublicQuestion(q) {
  return { id: q.id, prompt: q.prompt, options: Array.isArray(q.options) ? q.options.slice() : [] };
}

/**
 * Build the game-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.repository]         game repository (pg or in-memory)
 * @param {object} [deps.questionProvider]   { list(), get(id) }
 * @param {object} [deps.eventPublisher]     { publishScore(gameId, score) }
 * @param {object} [deps.verifier]           OIDC verifier
 * @param {object} [deps.userRepository]     sub -> id mapping
 * @param {object} [deps.logger]             logger (default console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const repository = deps.repository;
  if (!repository) throw new Error('game-service requires a repository');
  const questionProvider = deps.questionProvider;
  if (!questionProvider) throw new Error('game-service requires a questionProvider');
  const eventPublisher = deps.eventPublisher || { publishScore: async () => {} };
  const verifier =
    deps.verifier ||
    oidc.createTokenVerifier({
      issuer: process.env.OIDC_ISSUER,
      audience: process.env.OIDC_AUDIENCE,
      jwksUri: process.env.OIDC_JWKS_URI,
    });
  const userRepository = deps.userRepository;
  if (!userRepository) throw new Error('game-service requires a userRepository');
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'game-service' });
  });

  // Shared auth helper for route handlers.
  async function requireOwner(req, res) {
    try {
      return await resolveOwner(userRepository, verifier, req.headers.authorization);
    } catch (err) {
      if (err && err.name === 'AuthError') {
        res.status(401).json({ error: 'unauthorized' });
        return null;
      }
      log.error('auth failed', err.message);
      res.status(500).json({ error: 'internal_error' });
      return null;
    }
  }

  /**
   * POST /api/games?questionIds=1,2,3
   *   body { questionIds?: number[] }   (reproducible practice)
   *   201 { id, questions:[{id,prompt,options}] }
   * The correctAnswer is never returned to the player.
   */
  app.post('/api/games', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    try {
      const requested = Array.isArray(req.body && req.body.questionIds)
        ? req.body.questionIds
        : null;

      let questions;
      if (requested && requested.length > 0) {
        questions = [];
        for (const qid of requested) {
          if (!Number.isInteger(qid) || qid <= 0) {
            return res.status(400).json({ error: 'invalid_question_id' });
          }
          const q = await questionProvider.get(qid);
          if (!q) return res.status(404).json({ error: 'question_not_found' });
          questions.push(q);
        }
      } else {
        questions = await questionProvider.list();
        // Stable order is guaranteed by the position column in the persistence
        // layer; the in-memory provider returns insertion order.
        if (!questions.length) {
          return res.status(404).json({ error: 'no_questions_available' });
        }
      }

      const game = await repository.create(ownerId, questions);
      await eventPublisher
        .publishScore(game.id, game.score)
        .catch((err) => log.warn('publishScore failed (non-fatal)', err.message));

      return res.status(201).json({
        id: game.id,
        state: GAME_STATE.IN_PROGRESS,
        questions: questions.map(toPublicQuestion),
      });
    } catch (err) {
      log.error('create game failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games -> 200 { games:[{id,state,score,questions}] } for the
   * authenticated owner, most recent first. Never includes correctAnswer. The
   * browser uses this to recover an in-flight game after a full page reload so
   * the score always comes from persisted PostgreSQL state.
   */
  app.get('/api/games', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;
    try {
      const games = await repository.listByOwner(ownerId);
      return res.status(200).json({
        games: games.map((g) => ({
          id: g.id,
          state: g.state,
          score: g.score,
          questions: (g.questions || []).map(toPublicQuestion),
        })),
      });
    } catch (err) {
      log.error('list games failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games/:id -> 200 game state (player view, never correctAnswer).
   * Other user's game -> 404 (do not leak existence).
   */
  app.get('/api/games/:id', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      return res.status(200).json({
        id: game.id,
        state: game.state,
        score: game.score,
        questions: (game.questions || []).map(toPublicQuestion),
      });
    } catch (err) {
      log.error('get game failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  // Shared pause/resume mutation helper.
  async function mutateState(req, res, nextState) {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      const updated = await repository.setState(id, nextState);
      return res.status(200).json({ id: updated.id, state: updated.state, score: updated.score });
    } catch (err) {
      log.error('set state failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  }

  app.post('/api/games/:id/pause', (req, res) => mutateState(req, res, GAME_STATE.PAUSED));
  app.post('/api/games/:id/resume', (req, res) => mutateState(req, res, GAME_STATE.IN_PROGRESS));

  /**
   * POST /api/games/:id/answers { questionId, answer }
   *   200 { correct:boolean, score:integer }
   *   400 malformed fraction / invalid payload
   *   409 paused game or repeated question
   * Scoring and dedup happen in one transaction in the repository.
   */
  app.post('/api/games/:id/answers', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    const body = req.body || {};
    const questionId = body.questionId;
    const answer = body.answer;
    if (!Number.isInteger(questionId) || questionId <= 0) {
      return res.status(400).json({ error: 'invalid_question_id' });
    }
    if (typeof answer !== 'string' || answer.trim() === '') {
      return res.status(400).json({ error: 'answer_must_be_string' });
    }

    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      if (game.state === GAME_STATE.PAUSED) {
        return res.status(409).json({ error: 'game_paused' });
      }
      // Validate the submitted answer is a well-formed fraction before scoring.
      const question = await questionProvider.get(questionId);
      if (!question) return res.status(404).json({ error: 'question_not_found' });
      const verdict = validateAnswer(question, answer);
      if (verdict.reason === 'answer_malformed') {
        return res.status(400).json({ error: 'malformed_fraction' });
      }

      // scoreAnswer deduplicates via UNIQUE(game_id, question_id); a repeat
      // throws a DuplicateAnswer error the repository surfaces as 409.
      const result = await repository.scoreAnswer(id, questionId, answer, verdict.correct);
      await eventPublisher
        .publishScore(id, result.score)
        .catch((err) => log.warn('publishScore failed (non-fatal)', err.message));

      return res.status(200).json({ correct: result.correct, score: result.score });
    } catch (err) {
      if (err && err.code === 'DUPLICATE_ANSWER') {
        return res.status(409).json({ error: 'answer_already_recorded' });
      }
      log.error('answer failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games/:id/score -> 200 { score:integer }. Other user -> 404.
   */
  app.get('/api/games/:id/score', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      return res.status(200).json({ score: game.score });
    } catch (err) {
      log.error('get score failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

/**
 * Build production dependencies (PostgreSQL repository, question pool provider
 * reading from the question-service's repository, RabbitMQ event publisher).
 * Kept lazy so the HTTP handler factory is importable in tests.
 */
function buildProductionDeps() {
  // Lazy requires keep the module importable without those files present until
  // a production runtime actually boots (test-time uses in-memory adapters).
  const { PgGameRepository } = require('./repository');
  const { RabbitMqEventPublisher } = require('./events');
  const { PgQuestionRepository } = require('../../question-service/src/repository');
  const { PgUserRepository } = require('../../user-service/src/index');

  const repository = new PgGameRepository(process.env.DATABASE_URL);
  const questionProvider = new PgQuestionRepository(process.env.DATABASE_URL);
  const userRepository = new PgUserRepository(process.env.DATABASE_URL);
  const eventPublisher = process.env.RABBITMQ_URL
    ? new RabbitMqEventPublisher(process.env.RABBITMQ_URL)
    : null;
  const verifier = oidc.createTokenVerifier({
    issuer: process.env.OIDC_ISSUER,
    audience: process.env.OIDC_AUDIENCE,
    jwksUri: process.env.OIDC_JWKS_URI,
  });
  return { repository, questionProvider, userRepository, eventPublisher, verifier };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  const deps = buildProductionDeps();
  const app = buildApp(deps);
  const server = app.listen(PORT, () => {
    console.log(`game-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  buildProductionDeps,
  resolveOwner,
  toPublicQuestion,
  GAME_STATE,
  GameServiceError,
};

'use strict';

/**
 * Game repository — persistence layer for the game service.
 *
 * Provides two implementations behind a common interface:
 *   - PgGameRepository: PostgreSQL 16 source of truth. Score mutations are
 *     serialized per game and deduplicated in a single transaction; repeats
 *     rely on the UNIQUE (game_id, question_id) constraint in the `answers`
 *     table (sql/migrations/001_schema.sql) and are surfaced with a
 *     DUPLICATE_ANSWER code so the route layer can return 409.
 *   - InMemoryGameRepository: dependency-injection test adapter so the default
 *     `npm test` runs without live PostgreSQL while still exercising
 *     deduplication and owner checks.
 *
 * Repository interface consumed by packages/game-service/src/index.js:
 *   create(ownerId, questions)               -> {id,state,score}
 *   get(id)                                  -> game|null (contains questions
 *                                               WITH correctAnswer for scoring;
 *                                               the route layer strips it)
 *   setState(id, state)                      -> {id,state,score}
 *   scoreAnswer(id, questionId, answer, correct) -> Promise<{correct,score}>
 *        throws {code:'DUPLICATE_ANSWER'} on a repeated question
 *
 * Game shape (internal):
 *   { id, ownerId, state, score, questions: [{id,prompt,options,correctAnswer}] }
 */

const { Pool } = require('pg');

/** Error thrown when a question has already been answered for a game (-> 409). */
class DuplicateAnswerError extends Error {
  constructor() {
    super('answer already recorded for this game');
    this.name = 'DuplicateAnswerError';
    this.code = 'DUPLICATE_ANSWER';
  }
}

/** snake_case game row -> internal game shape (questions filled separately). */
function rowToGame(row) {
  return {
    id: row.id,
    ownerId: row.owner_id,
    state: row.state,
    score: row.score,
    questions: [],
  };
}

/** snake_case question row -> internal question shape (correctAnswer kept). */
function rowToGameQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: Array.isArray(row.options) ? row.options.slice() : [],
    correctAnswer: row.correct_answer,
  };
}

/**
 * PostgreSQL-backed game repository.
 *
 * The pg Client opens its connection lazily (on first use) so the HTTP listener
 * can boot before Postgres is reachable; bounded downstream timeouts are layered
 * on by the service/gateway.
 *
 * Concurrency contract (space-fractions.md line 48): score updates serialize per
 * game via `SELECT ... FOR UPDATE` on the games row inside one owned
 * transaction. Both the answer INSERT and the score UPDATE happen in the same
 * transaction; the UNIQUE (game_id, question_id) constraint becomes the dedup
 * guard (no EXCLUDED in RETURNING — illegal on PG16). On any error the
 * transaction rolls back.
 */
class PgGameRepository {
  constructor(connectionString) {
    // A pool (not a single Client) so concurrent requests each obtain their own
    // connection. This is essential for scoreAnswer: it runs an explicit
    // BEGIN/COMMIT transaction, and eight concurrent answers to the same game
    // must not interleave on one shared connection (that corrupts transaction
    // state and produces the "no transaction in progress" 500s).
    this.pool = new Pool({ connectionString, max: 10 });
  }

  /**
   * Run `fn` on a dedicated client from the pool, releasing the client back
   * afterwards (and on error). Single-connection operations use this helper so
   * concurrent requests never share a connection.
   */
  async _withClient(fn) {
    const client = await this.pool.connect();
    try {
      return await fn(client);
    } finally {
      client.release();
    }
  }

  async create(ownerId, questions) {
    return this._withClient(async (client) => {
      await client.query('BEGIN');
      try {
        const gameRes = await client.query(
          `INSERT INTO games (owner_id, state, score)
           VALUES ($1, 'in_progress', 0)
           RETURNING id, owner_id, state, score`,
          [ownerId],
        );
        const game = rowToGame(gameRes.rows[0]);

        // Insert the ordered question set; position preserves stable order.
        for (let i = 0; i < questions.length; i += 1) {
          await client.query(
            `INSERT INTO game_questions (game_id, question_id, position)
             VALUES ($1, $2, $3)`,
            [game.id, questions[i].id, i],
          );
        }

        await client.query('COMMIT');

        // Attach the question records (including correctAnswer) for scoring
        // and the player-facing view (the route strips correctAnswer).
        game.questions = questions.map((q) => ({
          id: q.id,
          prompt: q.prompt,
          options: Array.isArray(q.options) ? q.options.slice() : [],
          correctAnswer: q.correctAnswer,
        }));
        return game;
      } catch (err) {
        await client.query('ROLLBACK');
        throw err;
      }
    });
  }

  /** Load a game and its ordered questions, with correctAnswer for scoring. */
  async _loadGame(client, id) {
    const res = await client.query(
      `SELECT id, owner_id, state, score FROM games WHERE id = $1`,
      [id],
    );
    if (!res.rows.length) return null;
    const game = rowToGame(res.rows[0]);

    const qRes = await client.query(
      `SELECT q.id, q.prompt, q.options, q.correct_answer
         FROM game_questions gq
         JOIN questions q ON q.id = gq.question_id
        WHERE gq.game_id = $1
        ORDER BY gq.position ASC`,
      [id],
    );
    game.questions = qRes.rows.map(rowToGameQuestion);
    return game;
  }

  async get(id) {
    return this._withClient((client) => this._loadGame(client, id));
  }

  /**
   * List games owned by a user, most recently created first, each loaded with
   * its ordered questions. Used by the browser to recover an in-flight game
   * after a full page reload (so the score is read from PostgreSQL rather than
   * trusting any client-stored value).
   */
  async listByOwner(ownerId) {
    return this._withClient(async (client) => {
      const res = await client.query(
        `SELECT id, owner_id, state, score FROM games
          WHERE owner_id = $1
          ORDER BY id DESC`,
        [ownerId],
      );
      const games = [];
      for (const row of res.rows) {
        const game = await this._loadGame(client, row.id);
        if (game) games.push(game);
      }
      return games;
    });
  }

  async setState(id, state) {
    return this._withClient(async (client) => {
      const res = await client.query(
        `UPDATE games SET state = $2, updated_at = now()
          WHERE id = $1
          RETURNING id, owner_id, state, score`,
        [id, state],
      );
      return res.rows.length ? rowToGame(res.rows[0]) : null;
    });
  }

  /**
   * Record an answer and increment the score atomically.
   *
   * @param {number} id          game id
   * @param {number} questionId
   * @param {string} answer      submitted answer string (stored verbatim)
   * @param {boolean} correct    whether the answer is correct (pre-computed)
   * @returns {Promise<{correct:boolean, score:number}>}
   * @throws DuplicateAnswerError if this question was already answered
   */
  async scoreAnswer(id, questionId, answer, correct) {
    return this._withClient(async (client) => {
      await client.query('BEGIN');
      try {
        // Serialize per game: lock the games row for the duration of the
        // transaction so concurrent answers to the same game cannot interleave.
        // Each request runs on its own pooled connection, so a second request
        // blocks on this row lock until the first commits (or rolls back),
        // then sees the committed answer row and returns 409 instead of 500.
        const lockRes = await client.query(
          `SELECT id, owner_id, state, score FROM games WHERE id = $1 FOR UPDATE`,
          [id],
        );
        if (!lockRes.rows.length) {
          await client.query('ROLLBACK');
          return null;
        }

        // Dedup guard: the UNIQUE (game_id, question_id) constraint also
        // protects this, but checking first gives a deterministic 409 without
        // relying on error-code parsing.
        const dup = await client.query(
          `SELECT 1 FROM answers WHERE game_id = $1 AND question_id = $2`,
          [id, questionId],
        );
        if (dup.rows.length) {
          await client.query('ROLLBACK');
          throw new DuplicateAnswerError();
        }

        await client.query(
          `INSERT INTO answers (game_id, question_id, answer, correct)
           VALUES ($1, $2, $3, $4)`,
          [id, questionId, answer, correct],
        );

        const updated = correct
          ? await client.query(
              `UPDATE games SET score = score + 1, updated_at = now()
                WHERE id = $1
                RETURNING id, owner_id, state, score`,
              [id],
            )
          : await client.query(
              `UPDATE games SET updated_at = now()
                WHERE id = $1
                RETURNING id, owner_id, state, score`,
              [id],
            );

        await client.query('COMMIT');
        const game = rowToGame(updated.rows[0]);
        return { correct, score: game.score };
      } catch (err) {
        await client.query('ROLLBACK').catch(() => {});
        throw err;
      }
    });
  }

  async close() {
    await this.pool.end();
  }
}

/**
 * In-memory game repository for unit tests. Mirrors the PostgreSQL semantics
 * including deduplication (repeat answer does not increment score and throws
 * DuplicateAnswerError) so route tests exercise real behavior without a live
 * database.
 */
class InMemoryGameRepository {
  constructor() {
    this.rows = new Map();
    this.answers = new Map(); // `${gameId}:${questionId}` -> true
    this.nextId = 1;
  }

  async create(ownerId, questions) {
    const id = this.nextId++;
    const game = {
      id,
      ownerId,
      state: 'in_progress',
      score: 0,
      questions: questions.map((q) => ({
        id: q.id,
        prompt: q.prompt,
        options: Array.isArray(q.options) ? q.options.slice() : [],
        correctAnswer: q.correctAnswer,
      })),
    };
    this.rows.set(id, game);
    return {
      id: game.id,
      ownerId: game.ownerId,
      state: game.state,
      score: game.score,
      questions: game.questions,
    };
  }

  async get(id) {
    const game = this.rows.get(id);
    if (!game) return null;
    return {
      id: game.id,
      ownerId: game.ownerId,
      state: game.state,
      score: game.score,
      questions: game.questions.map((q) => ({ ...q, options: q.options.slice() })),
    };
  }

  async setState(id, state) {
    const game = this.rows.get(id);
    if (!game) return null;
    game.state = state;
    return { id: game.id, ownerId: game.ownerId, state: game.state, score: game.score };
  }

  async listByOwner(ownerId) {
    const games = [];
    for (const game of this.rows.values()) {
      if (game.ownerId === ownerId) games.push(game);
    }
    games.sort((a, b) => b.id - a.id);
    return games.map((game) => ({
      id: game.id,
      ownerId: game.ownerId,
      state: game.state,
      score: game.score,
      questions: game.questions.map((q) => ({ ...q, options: q.options.slice() })),
    }));
  }

  async scoreAnswer(id, questionId, answer, correct) {
    const game = this.rows.get(id);
    if (!game) return null;
    const key = `${id}:${questionId}`;
    if (this.answers.has(key)) {
      throw new DuplicateAnswerError();
    }
    this.answers.set(key, true);
    if (correct) game.score += 1;
    return { correct, score: game.score };
  }

  async close() {
    this.rows.clear();
    this.answers.clear();
  }
}

module.exports = {
  PgGameRepository,
  InMemoryGameRepository,
  DuplicateAnswerError,
  rowToGame,
  rowToGameQuestion,
};

'use strict';

/**
 * Space Fractions gateway — public edge (container port 3000).
 *
 * Responsibilities (space-fractions.md lines 15-24, 30-31):
 *   - GET /health -> 200 (orchestration/liveness probe).
 *   - Serve the plain browser UI (HTML/CSS/JS, no bundler) at "/".
 *   - Reverse-proxy authenticated API requests to the downstream services
 *     (game-service, question-service, user-service, admin-service), forwarding
 *     the Bearer OIDC access token verbatim so each service enforces its own
 *     authorization boundary.
 *   - Bounded downstream timeouts + error handling: a slow/unreachable service
 *     yields a 504/502, never an open socket.
 *   - Publish Prometheus metrics on GET /metrics.
 *   - Original GET /play backwards compatibility -> creates a practice game and
 *     returns { gameId } (Architecture_Documentation.md line 105).
 *
 * The gateway holds no domain state and performs no scoring/authorization of
 * its own. It computes the public browser origin from PUBLIC_ORIGIN (never a
 * hard-coded host:port) so Keycloak redirects work across remapped test ports.
 *
 * A reverse proxy with bounded timeouts is implemented on Node's built-in
 * `http` + global `fetch` (bounded via AbortController) rather than adding a
 * third-party proxy, keeping the runtime surface small and unit-testable —
 * injectable `routes`/`request` dependencies (see `buildApp`).
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = Number(process.env.PORT || 3000);

/** Per-downstream bounded timeout (ms) for API fan-out. */
const DOWNSTREAM_TIMEOUT_MS = Number(process.env.GATEWAY_TIMEOUT_MS || 10000);

/** Maximum forwarded request body (aligns with each service's `1mb` JSON limit). */
const MAX_BODY_BYTES = 1024 * 1024;

/** Default public-facing origin used for browser redirects/links. */
function publicOrigin() {
  return process.env.PUBLIC_ORIGIN || `http://localhost:${PORT}`;
}

/**
 * Build the browser-facing OIDC/client configuration served at /config.js.
 * The browser must never hard-code a Keycloak host:port, because the
 * acceptance harness remaps the identity-provider public origin and the
 * gateway public origin independently. Values derive from the environment:
 *
 *   - issuer: OIDC_ISSUER (public issuer URL), fallback OIDC_PUBLIC_ORIGIN +
 *     '/realms/space-fractions'.
 *   - redirectUri: PUBLIC_ORIGIN + '/' (where the browser actually reaches the
 *     gateway, and where Keycloak redirects the authorization code).
 *   - clientId: OIDC_CLIENT_ID (default 'space-fractions-client').
 */
function buildClientConfig(deps = {}) {
  const origin = (deps.publicOrigin || publicOrigin()).replace(/\/$/, '');
  const issuerEnv = deps.issuer || process.env.OIDC_ISSUER;
  const publicIssuer = deps.oidcPublicOrigin || process.env.OIDC_PUBLIC_ORIGIN;
  const issuer = issuerEnv
    ? issuerEnv.replace(/\/$/, '')
    : (publicIssuer ? `${publicIssuer.replace(/\/$/, '')}/realms/space-fractions` : `http://localhost:8080/realms/space-fractions`);
  return {
    issuer,
    clientId: deps.clientId || process.env.OIDC_CLIENT_ID || 'space-fractions-client',
    redirectUri: `${origin}/`,
    scope: deps.scope || process.env.OIDC_SCOPE || 'openid profile',
  };
}

function clientConfigJs(config) {
  return (
    `window.SPACE_FRACTIONS_CONFIG = ${JSON.stringify(config)};\n`
  );
}

/**
 * Read the static UI directory once (memoized). Returns a map of
 * relative-path -> { contentType, body } for every file under `public/`.
 */
function loadStaticAssets(staticDir) {
  const dir = staticDir || path.join(__dirname, '..', 'public');
  const assets = new Map();
  const walkAndRead = (base, relative) => {
    const entries = fs.readdirSync(base, { withFileTypes: true });
    for (const entry of entries) {
      const abs = path.join(base, entry.name);
      const rel = relative ? `${relative}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        walkAndRead(abs, rel);
      } else {
        assets.set(`/${rel}`, {
          contentType: contentTypeFor(rel),
          body: fs.readFileSync(abs),
        });
      }
    }
  };
  walkAndRead(dir, '');
  return assets;
}

function contentTypeFor(file) {
  if (file.endsWith('.html')) return 'text/html; charset=utf-8';
  if (file.endsWith('.css')) return 'text/css; charset=utf-8';
  if (file.endsWith('.js')) return 'application/javascript; charset=utf-8';
  if (file.endsWith('.json')) return 'application/json; charset=utf-8';
  if (file.endsWith('.svg')) return 'image/svg+xml';
  return 'application/octet-stream';
}

/**
 * Lightweight metrics registry (no external client required for the core
 * counters). Exposed as the standard Prometheus text format. Counters:
 *   http_requests_total{method,path,status}
 *   downstream_requests_total{service,status}
 *   downstream_timeouts_total{service}
 */
function createMetrics() {
  const counters = new Map();
  const inc = (name, labels) => {
    const key = `${name}{${Object.entries(labels).map(([k, v]) => `${k}="${v}"`).join(',')}}`;
    counters.set(key, (counters.get(key) || 0) + 1);
  };
  return {
    inc,
    render() {
      const lines = [];
      for (const [key, value] of counters.entries()) {
        lines.push(`${key} ${value}`);
      }
      return `${lines.join('\n')}\n`;
    },
  };
}

/**
 * Message shape expected from a downstream service URL: either a base URL
 * string, or an object { base, service } where `service` is the metrics label.
 */
function resolveTarget(entry) {
  if (typeof entry === 'string') return { base: entry, service: entry };
  return { base: entry.base, service: entry.service };
}

/**
 * Build the gateway HTTP request handler.
 *
 * @param {object} [deps]
 * @param {Map<string,object>} [deps.assets]  static asset map (loadStaticAssets)
 * @param {object}            [deps.routes]  { prefix: string|{base,service} }
 *   mapping URL prefixes to downstream base URLs (e.g. { '/api/games': 'http://game-service:3001' }).
 * @param {function}          [deps.fetch]   fetch implementation (default global fetch)
 * @param {object}            [deps.metrics] metrics registry (default createMetrics())
 * @param {object}            [deps.logger]  logger (default console)
 * @returns {http.RequestListener}
 */
function buildApp(deps = {}) {
  const assets = deps.assets || loadStaticAssets();
  const routes = deps.routes || defaultRoutes();
  const fetchImpl = deps.fetch || globalThis.fetch;
  const metrics = deps.metrics || createMetrics();
  const log = deps.logger || console;
  const origin = deps.publicOrigin || publicOrigin();
  const clientConfig = buildClientConfig(deps);

  async function readBody(req) {
    const chunks = [];
    let size = 0;
    for await (const chunk of req) {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        const err = new Error('request body too large');
        err.status = 413;
        throw err;
      }
      chunks.push(chunk);
    }
    return Buffer.concat(chunks);
  }

  function respond(res, status, headers, body) {
    res.writeHead(status, headers);
    res.end(body);
  }

  function json(res, status, obj) {
    respond(
      res,
      status,
      { 'content-type': 'application/json; charset=utf-8' },
      JSON.stringify(obj),
    );
  }

  /**
   * Forward an incoming request to the selected downstream target with a
   * bounded timeout. Returns { status, headers, body } on success; throws on
   * timeout (504) or refusal (502).
   */
  async function forward(req, target, body) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), DOWNSTREAM_TIMEOUT_MS);
    const url = new URL(req.url, target.base);
    try {
      const upstream = await fetchImpl(url.toString(), {
        method: req.method,
        headers: {
          'content-type': req.headers['content-type'] || 'application/json',
          // Forward the Bearer token verbatim so downstream services authorize.
          ...(req.headers.authorization
            ? { authorization: req.headers.authorization }
            : {}),
          accept: 'application/json',
        },
        body: req.method === 'GET' || req.method === 'HEAD' ? undefined : body,
        signal: controller.signal,
      });
      const resBody = await upstream.arrayBuffer();
      return {
        status: upstream.status,
        headers: upstream.headers,
        body: Buffer.from(resBody),
      };
    } catch (err) {
      if (err && err.name === 'AbortError') {
        const e = new Error(`downstream timeout: ${target.service}`);
        e.status = 504;
        throw e;
      }
      const e = new Error(`downstream unavailable: ${target.service}`);
      e.status = 502;
      throw e;
    } finally {
      clearTimeout(timer);
    }
  }

  function forwardableHeaders(headers) {
    const out = { 'content-type': 'application/json; charset=utf-8' };
    for (const key of ['content-type', 'cache-control', 'etag']) {
      if (headers && headers.get && headers.get(key)) out[key] = headers.get(key);
    }
    return out;
  }

  async function handle(req, res) {
    const parsed = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const pathname = parsed.pathname;
    const start = Date.now();

    try {
      // Liveness/readiness.
      if (pathname === '/health') {
        metrics.inc('http_requests_total', { method: 'GET', path: '/health', status: 200 });
        return json(res, 200, { status: 'ok', service: 'gateway' });
      }

      // Prometheus scrape endpoint.
      if (pathname === '/metrics') {
        metrics.inc('http_requests_total', { method: 'GET', path: '/metrics', status: 200 });
        return respond(res, 200, { 'content-type': 'text/plain; version=0.0.4; charset=utf-8' }, metrics.render());
      }

      // Browser OIDC/client config, generated at runtime from env so the UI
      // never hard-codes an identity-provider or gateway host:port.
      if (pathname === '/config.js' && (req.method === 'GET' || req.method === 'HEAD')) {
        metrics.inc('http_requests_total', { method: req.method, path: '/config.js', status: 200 });
        return respond(res, 200, { 'content-type': 'application/javascript; charset=utf-8', 'cache-control': 'no-cache' },
          req.method === 'HEAD' ? undefined : clientConfigJs(clientConfig));
      }

      // Original GET /play compatibility -> create a practice game, return gameId.
      if (pathname === '/play' && req.method === 'GET') {
        const gameTarget = resolveTarget(routes['/api/games']);
        const body = Buffer.from('{}');
        const { status, headers, body: resBody } = await forward(
          { ...req, url: '/api/games', method: 'POST' },
          gameTarget,
          body,
        );
        let gameId = null;
        try {
          const created = JSON.parse(resBody.toString('utf8'));
          gameId = created.id;
        } catch {
          /* downstream already errored */
        }
        const finalStatus = status < 400 && gameId ? 200 : status;
        metrics.inc('downstream_requests_total', { service: gameTarget.service, status });
        metrics.inc('http_requests_total', { method: 'GET', path: '/play', status: finalStatus });
        if (gameId) return json(res, finalStatus, { gameId });
        return respond(res, status, forwardableHeaders(headers), resBody);
      }

      // Static UI (served at "/", plus assets referenced by index.html).
      if (req.method === 'GET' || req.method === 'HEAD') {
        const assetPath = pathname === '/' ? '/index.html' : pathname;
        const asset = assets.get(assetPath);
        if (asset) {
          metrics.inc('http_requests_total', { method: req.method, path: pathname, status: 200 });
          const headers = { 'content-type': asset.contentType, 'cache-control': 'no-cache' };
          return respond(res, 200, headers, req.method === 'HEAD' ? undefined : asset.body);
        }
      }

      // API fan-out: longest matching prefix.
      const matching = Object.keys(routes)
        .filter((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`))
        .sort((a, b) => b.length - a.length)[0];
      if (matching) {
        const target = resolveTarget(routes[matching]);
        const body = req.method === 'GET' || req.method === 'HEAD' ? undefined : await readBody(req);
        const { status, headers, body: resBody } = await forward(req, target, body);
        metrics.inc('downstream_requests_total', { service: target.service, status });
        metrics.inc('http_requests_total', { method: req.method, path: pathname, status });
        return respond(res, status, forwardableHeaders(headers), resBody);
      }

      metrics.inc('http_requests_total', { method: req.method, path: pathname, status: 404 });
      return json(res, 404, { error: 'not_found' });
    } catch (err) {
      const status = err && err.status ? err.status : 500;
      log.error(`gateway error on ${req.method} ${pathname}`, err.message);
      metrics.inc('http_requests_total', { method: req.method, path: pathname, status });
      if (status === 504) {
        const serviceLabel = (err.service || 'unknown');
        metrics.inc('downstream_timeouts_total', { service: serviceLabel });
      }
      return json(res, status, { error: status === 504 ? 'gateway_timeout' : status === 502 ? 'bad_gateway' : 'internal_error' });
    }
  }

  return handle;
}

/** Default downstream routes resolved from env with container defaults. */
function defaultRoutes() {
  return {
    '/api/games': process.env.GAME_SERVICE_URL || 'http://game-service:3001',
    '/api/questions': process.env.QUESTION_SERVICE_URL || 'http://question-service:3002',
    '/api/users': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/users': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/auth': process.env.USER_SERVICE_URL || 'http://user-service:3003',
    '/api/admin': process.env.ADMIN_SERVICE_URL || 'http://admin-service:3004',
  };
}

/**
 * Start the gateway HTTP listener (kept alive until SIGTERM/SIGINT).
 * The listener stays alive independently of downstream availability, so the
 * startup probe passes even before backing services are ready.
 */
function startServer(app, port) {
  const server = http.createServer(app);
  server.listen(port, () => {
    console.log(`gateway listening on :${port}`);
  });
  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
  return server;
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  startServer(buildApp(process.env.GATEWAY_STATIC_DIR ? {
    assets: loadStaticAssets(process.env.GATEWAY_STATIC_DIR),
  } : {}), PORT);
}

module.exports = {
  buildApp,
  loadStaticAssets,
  createMetrics,
  defaultRoutes,
  startServer,
  publicOrigin,
  buildClientConfig,
  clientConfigJs,
  contentTypeFor,
};

use strict';

/**
 * Space Fractions browser UI (plain JS, no bundler).
 *
 * The gateway serves this file as a static asset. All API calls go through the
 * same origin (the gateway) and carry the OIDC access token in a Bearer
 * header. The token is obtained via the authorization-code + PKCE (S256) flow
 * documented below. Player responses never expose `correctAnswer` — the UI
 * only reads `correct` (boolean) and `score` (integer).
 *
 * Views are simple <section> elements toggled by a `show(view)` helper; the
 * game state (id/questions/index/score/paused) is kept in `game`.
 */

(function () {
  'use strict';

  // ---------------------------------------------------------------------
  // OIDC configuration (derived from gateway env via a small /config.json
  // if present, otherwise sensible local-only defaults). Real deployments
  // set PUBLIC_ORIGIN and OIDC_ISSUER; the gateway exposes these to the
  // browser through a static config file so redirects never hard-code a
  // host:port (test runtimes remap ports).
  // ---------------------------------------------------------------------
  const CONFIG = window.SPACE_FRACTIONS_CONFIG || {};

  const ISSUER = CONFIG.issuer || 'http://localhost:8080/realms/space-fractions';
  const CLIENT_ID = CONFIG.clientId || 'space-fractions-client';
  const REDIRECT_URI =
    CONFIG.redirectUri || `${window.location.origin}/`;
  const SCOPE = CONFIG.scope || 'openid profile';

  // Token storage. `accessToken` is acquired at sign-in via PKCE.
  let accessToken = sessionStorage.getItem('space-fractions.access_token') || null;
  let idToken = sessionStorage.getItem('space-fractions.id_token') || null;
  let profile = null;

  // Active game state (never includes correctAnswer).
  let game = {
    id: null,
    questions: [],
    current: 0,
    score: 0,
    paused: false,
    answered: new Set(), // question ids already answered
  };

  // ---------------------------------------------------------------------
  // Small DOM helpers
  // ---------------------------------------------------------------------
  const $ = (sel) => document.querySelector(sel);

  function show(viewId) {
    document.querySelectorAll('.view').forEach((v) => (v.hidden = v.id !== viewId));
  }

  function setAuthUI() {
    const loggedIn = !!accessToken && !!profile;
    $('#login-btn').hidden = loggedIn;
    $('#logout-btn').hidden = !loggedIn;
    $('#user-name').hidden = !loggedIn;
    if (loggedIn && profile) {
      $('#user-name').textContent = profile.preferred_username || profile.name || profile.sub || 'user';
    }
  }

  function clearFeedback() {
    const fb = $('#answer-feedback');
    fb.hidden = true;
    fb.textContent = '';
  }

  function setFeedback(text, ok) {
    const fb = $('#answer-feedback');
    fb.hidden = false;
    fb.textContent = text;
    fb.className = `feedback ${ok ? 'correct' : 'incorrect'}`;
  }

  // ---------------------------------------------------------------------
  // Auth: authorization-code + PKCE (S256)
  // ---------------------------------------------------------------------
  function base64url(buf) {
    if (typeof buf === 'string') buf = new TextEncoder().encode(buf);
    let str = '';
    const bytes = new Uint8Array(buf);
    const CHUNK = 0x8000;
    for (let i = 0; i < bytes.length; i += CHUNK) {
      str += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
    }
    return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  function randomString(len) {
    const arr = new Uint8Array(len);
    crypto.getRandomValues(arr);
    return base64url(arr);
  }

  async function sha256(str) {
    return crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
  }

  async function buildAuthorizeUrl() {
    const verifier = randomString(64);
    const challenge = base64url(await sha256(verifier));
    sessionStorage.setItem('space-fractions.pkce_verifier', verifier);
    const state = randomString(32);
    sessionStorage.setItem('space-fractions.oauth_state', state);

    const params = new URLSearchParams({
      response_type: 'code',
      client_id: CLIENT_ID,
      redirect_uri: REDIRECT_URI,
      scope: SCOPE,
      state,
      code_challenge: challenge,
      code_challenge_method: 'S256',
    });
    return `${ISSUER.replace(/\/$/, '')}/protocol/openid-connect/auth?${params.toString()}`;
  }

  function decodeJwtPayload(token) {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    try {
      const payload = parts[1].replace(/-/g, '+').replace(/_/g, '/');
      const padded = payload + '='.repeat((4 - (payload.length % 4)) % 4);
      return JSON.parse(atob(padded));
    } catch {
      return null;
    }
  }

  async function exchangeCode(code) {
    const verifier = sessionStorage.getItem('space-fractions.pkce_verifier');
    const tokenUrl = `${ISSUER.replace(/\/$/, '')}/protocol/openid-connect/token`;
    const body = new URLSearchParams({
      grant_type: 'authorization_code',
      code,
      redirect_uri: REDIRECT_URI,
      client_id: CLIENT_ID,
      code_verifier: verifier,
    });
    const res = await fetch(tokenUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: body.toString(),
    });
    if (!res.ok) throw new Error('token exchange failed');
    const data = await res.json();
    accessToken = data.access_token;
    idToken = data.id_token || null;
    sessionStorage.setItem('space-fractions.access_token', accessToken);
    if (idToken) sessionStorage.setItem('space-fractions.id_token', idToken);
    profile = idToken ? decodeJwtPayload(idToken) : (accessToken ? decodeJwtPayload(accessToken) : null);
  }

  async function handleRedirect() {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('code');
    const state = params.get('state');
    const storedState = sessionStorage.getItem('space-fractions.oauth_state');
    if (!code) return false;
    if (!storedState || state !== storedState) {
      console.error('OAuth state mismatch');
      return false;
    }
    await exchangeCode(code);
    sessionStorage.removeItem('space-fractions.pkce_verifier');
    sessionStorage.removeItem('space-fractions.oauth_state');
    window.history.replaceState({}, document.title, REDIRECT_URI);
    setAuthUI();
    return true;
  }

  async function signIn() {
    window.location.assign(await buildAuthorizeUrl());
  }

  function signOut() {
    accessToken = null;
    idToken = null;
    profile = null;
    sessionStorage.removeItem('space-fractions.access_token');
    sessionStorage.removeItem('space-fractions.id_token');
    sessionStorage.removeItem('space-fractions.game_id');
    resetGame();
    show('view-intro');
    setAuthUI();
  }

  // ---------------------------------------------------------------------
  // API helper (adds Bearer token; maps status to typed errors)
  // ---------------------------------------------------------------------
  async function api(method, url, body) {
    const headers = { accept: 'application/json' };
    if (accessToken) headers.authorization = `Bearer ${accessToken}`;
    let payload;
    if (body !== undefined) {
      headers['content-type'] = 'application/json';
      payload = JSON.stringify(body);
    }
    const res = await fetch(url, { method, headers, body: payload });
    let data = null;
    const text = await res.text();
    if (text) {
      try {
        data = JSON.parse(text);
      } catch {
        data = { raw: text };
      }
    }
    if (!res.ok) {
      const err = new Error(data && data.error ? data.error : `HTTP ${res.status}`);
      err.status = res.status;
      err.data = data;
      throw err;
    }
    return data;
  }

  function handleApiError(err) {
    if (err.status === 401) {
      setFeedback('Please sign in to continue.', false);
      show('view-intro');
      setAuthUI();
      return;
    }
    setFeedback(err.message || 'Something went wrong.', false);
  }

  // ---------------------------------------------------------------------
  // Game flow
  // ---------------------------------------------------------------------
  function resetGame() {
    game = {
      id: null,
      questions: [],
      current: 0,
      score: 0,
      paused: false,
      answered: new Set(),
    };
    clearFeedback();
  }

  async function startGame() {
    if (!accessToken) {
      await signIn();
      return;
    }
    resetGame();
    try {
      const created = await api('POST', '/api/games', {});
      game.id = created.id;
      game.questions = created.questions || [];
      game.score = 0;
      game.current = 0;
      sessionStorage.setItem('space-fractions.game_id', String(created.id));
      if (game.questions.length === 0) {
        setFeedback('No questions available yet.', false);
        show('view-menu');
        return;
      }
      renderQuestion();
      show('view-play');
    } catch (err) {
      handleApiError(err);
    }
  }

  function renderQuestion() {
    const q = game.questions[game.current];
    if (!q) return;
    $('#question-index').textContent = String(game.current + 1);
    $('#question-prompt').textContent = q.prompt;
    const optionsEl = $('#question-options');
    optionsEl.innerHTML = '';
    (q.options || []).forEach((opt) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'option';
      btn.textContent = opt;
      btn.addEventListener('click', () => {
        $('#answer-input').value = opt;
      });
      optionsEl.appendChild(btn);
    });
    $('#answer-input').value = '';
    clearFeedback();
    updateScoreDisplay();
  }

  function updateScoreDisplay() {
    $('#score-value').textContent = String(game.score);
  }

  async function submitAnswer(answer) {
    if (!game.id) return;
    const q = game.questions[game.current];
    if (!q) return;
    try {
      const result = await api('POST', `/api/games/${game.id}/answers`, {
        questionId: q.id,
        answer,
      });
      if (result.correct) {
        // Only count one point; the server dedupes repeats.
        game.score = result.score;
      } else {
        game.score = result.score;
      }
      game.answered.add(q.id);
      updateScoreDisplay();
      if (result.correct) {
        setFeedback('Correct! +1', true);
      } else {
        setFeedback('Not quite. Try the next question.', false);
      }
      // Move to next question (or finish).
      if (game.current + 1 < game.questions.length) {
        game.current += 1;
        renderQuestion();
      } else {
        await finishGame();
      }
    } catch (err) {
      if (err.status === 409) {
        setFeedback('You already answered that question.', false);
      } else {
        handleApiError(err);
      }
    }
  }

  async function pauseGame() {
    if (!game.id) return;
    try {
      await api('POST', `/api/games/${game.id}/pause`, {});
      game.paused = true;
      show('view-paused');
    } catch (err) {
      handleApiError(err);
    }
  }

  async function resumeGame() {
    if (!game.id) return;
    try {
      await api('POST', `/api/games/${game.id}/resume`, {});
      game.paused = false;
      show('view-play');
    } catch (err) {
      if (err.status === 409) {
        setFeedback('Game is already resumed.', false);
        game.paused = false;
        show('view-play');
      } else {
        handleApiError(err);
      }
    }
  }

  async function finishGame() {
    try {
      const scoreRes = await api('GET', `/api/games/${game.id}/score`);
      game.score = scoreRes.score;
      $('#ending-text').textContent =
        `You answered all ${game.questions.length} question(s). Final score: ${game.score}.`;
      show('view-ending');
    } catch (err) {
      handleApiError(err);
    }
  }

  async function viewScore() {
    // After a full page reload the in-memory `game` is empty; recover the
    // authenticated user's most recent game from the server so the score is
    // the real persisted value, not a client-side guess.
    if (!game.id) {
      const recovered = await recoverGame();
      if (!recovered) return;
    }
    try {
      const scoreRes = await api('GET', `/api/games/${game.id}/score`);
      game.score = scoreRes.score;
      $('#final-score').textContent = String(scoreRes.score);
      show('view-score');
    } catch (err) {
      handleApiError(err);
    }
  }

  /**
   * Rebuild the active game from server-side persisted state after a reload.
   * Prefers the game id remembered in sessionStorage, but falls back to the
   * user's most recent game via GET /api/games so a reload never leaves the
   * user stranded on the Main Menu.
   *
   * @returns {Promise<boolean>} true if a game was recovered
   */
  async function recoverGame() {
    if (!accessToken) return false;
    try {
      const storedId = sessionStorage.getItem('space-fractions.game_id');
      let recovered = null;
      if (storedId) {
        try {
          recovered = await api('GET', `/api/games/${storedId}`);
        } catch (err) {
          // Stale id (e.g. game finished/deleted) -> fall through to list.
          recovered = null;
        }
      }
      if (!recovered) {
        const data = await api('GET', '/api/games');
        const games = (data && data.games) || [];
        if (games.length === 0) {
          show('view-menu');
          return false;
        }
        // Most recent game first (server orders by id DESC).
        recovered = games[0];
      }
      game.id = recovered.id;
      game.questions = recovered.questions || [];
      game.score = typeof recovered.score === 'number' ? recovered.score : 0;
      game.current = 0;
      game.answered = new Set();
      sessionStorage.setItem('space-fractions.game_id', String(recovered.id));
      updateScoreDisplay();
      return true;
    } catch (err) {
      handleApiError(err);
      return false;
    }
  }

  // ---------------------------------------------------------------------
  // Admin question CRUD (only shown to admins; server enforces 403)
  // ---------------------------------------------------------------------
  async function isAdmin() {
    if (!accessToken) return false;
    // Roles may be present on the access token payload (resource_access or
    // realm_access) or on the id_token profile. Try each location in turn.
    const sources = [];
    if (profile && profile.realm_access && Array.isArray(profile.realm_access.roles)) {
      sources.push(profile.realm_access.roles);
    }
    if (profile && profile.resource_access) {
      const ra = profile.resource_access[CLIENT_ID];
      if (ra && Array.isArray(ra.roles)) sources.push(ra.roles);
    }
    const accessPayload = accessToken ? decodeJwtPayload(accessToken) : null;
    if (accessPayload && accessPayload.realm_access && Array.isArray(accessPayload.realm_access.roles)) {
      sources.push(accessPayload.realm_access.roles);
    }
    if (accessPayload && accessPayload.resource_access) {
      const ra = accessPayload.resource_access[CLIENT_ID];
      if (ra && Array.isArray(ra.roles)) sources.push(ra.roles);
    }
    return sources.some((roles) => roles.includes('admin'));
  }

  function setAdminFeedback(text, ok) {
    const fb = $('#admin-feedback');
    fb.hidden = false;
    fb.textContent = text;
    fb.className = `feedback ${ok ? 'correct' : 'incorrect'}`;
  }

  async function renderAdmin() {
    const adminBtn = $('#menu-admin-btn');
    const admin = await isAdmin();
    if (adminBtn) adminBtn.hidden = !admin;
    if (admin) await listQuestions();
  }

  async function listQuestions() {
    const listEl = $('#admin-question-list');
    if (!listEl) return;
    listEl.innerHTML = '';
    try {
      const data = await api('GET', '/api/admin/questions');
      const questions = (data && data.questions) || [];
      if (questions.length === 0) {
        const li = document.cr

eateElement('li');
        li.textContent = 'No questions yet.';
        li.className = 'q-text';
        listEl.appendChild(li);
        return;
      }
      questions.forEach((q) => {
        const li = document.createElement('li');
        const span = document.createElement('span');
        span.className = 'q-text';
        span.textContent = q.prompt;
        const del = document.createElement('button');
        del.type = 'button';
        del.className = 'btn';
        del.textContent = 'Delete';
        del.addEventListener('click', () => deleteQuestion(q.id));
        li.appendChild(span);
        li.appendChild(del);
        listEl.appendChild(li);
      });
    } catch (err) {
      setAdminFeedback(err.message || 'Failed to load questions.', false);
    }
  }

  async function createQuestion(prompt, options, correctAnswer) {
    const data = await api('POST', '/api/admin/questions', { prompt, options, correctAnswer });
    setAdminFeedback(`Created question "${data.prompt}".`, true);
    await listQuestions();
  }

  async function deleteQuestion(id) {
    await api('DELETE', `/api/admin/questions/${id}`);
    setAdminFeedback('Question deleted.', true);
    await listQuestions();
  }

  function handleAdminCreateForm(e) {
    e.preventDefault();
    const prompt = $('#admin-prompt').value.trim();
    const optionsRaw = $('#admin-options').value.trim();
    const correctAnswer = $('#admin-correct').value.trim();
    if (!prompt || !correctAnswer) {
      setAdminFeedback('Prompt and correct answer are required.', false);
      return;
    }
    const options = optionsRaw
      .split(',')
      .map((s) => s.trim())
      .filter((s) => s.length > 0);
    createQuestion(prompt, options, correctAnswer).catch((err) => {
      setAdminFeedback(err.message || 'Failed to create question.', false);
    });
    // Reset the form but keep the question list visible.
    $('#admin-prompt').value = '';
    $('#admin-options').value = '';
    $('#admin-correct').value = '';
  }

  // ---------------------------------------------------------------------
  // Event wiring
  // ---------------------------------------------------------------------
  function bindEvents() {
    $('#login-btn').addEventListener('click', signIn);
    $('#logout-btn').addEventListener('click', signOut);

    $('#start-btn').addEventListener('click', startGame);
    $('#menu-play-btn').addEventListener('click', startGame);
    $('#menu-score-btn').addEventListener('click', viewScore);
    $('#menu-help-btn').addEventListener('click', () => show('view-help'));
    $('#menu-admin-btn').addEventListener('click', () => show('view-admin'));

    $('#admin-create-form').addEventListener('submit', handleAdminCreateForm);
    $('#admin-list-btn').addEventListener('click', listQuestions);

    $('#answer-form').addEventListener('submit', (e) => {
      e.preventDefault();
      const val = $('#answer-input').value.trim();
      if (!val) return;
      submitAnswer(val);
    });

    $('#pause-btn').addEventListener('click', pauseGame);
    $('#resume-btn').addEventListener('click', resumeGame);
    $('#paused-resume-btn').addEventListener('click', resumeGame);

    $('#ending-menu-btn').addEventListener('click', () => show('view-menu'));
    $('#score-menu-btn').addEventListener('click', () => show('view-menu'));
    $('#help-menu-btn').addEventListener('click', () => show('view-menu'));
  }

  async function init() {
    bindEvents();
    setAuthUI();
    // Try to load a fresh profile if a token already exists but profile is null.
    if (accessToken && !profile) {
      profile = idToken ? decodeJwtPayload(idToken) : decodeJwtPayload(accessToken);
    }
    const handled = await handleRedirect();
    if (!handled) {
      // Restore session from storage if present (no redirect to process).
      if (accessToken) {
        show('view-menu');
      } else {
        show('view-intro');
      }
    }
    setAuthUI();
    if (accessToken) {
      await renderAdmin();
    }
  }

  document.addEventListener('DOMContentLoaded', init);
})();

'use strict';

/**
 * Game service — session lifecycle and scoring for Space Fractions.
 *
 * Responsibilities (space-fractions.md lines 17-24, 47-50; Architecture_View
 * Lines 79-145 ProcessView):
 *   - Create a game from the question pool (or an explicit questionIds list for
 *     reproducible practice). Never expose `correctAnswer` to players.
 *   - Fetch game state, pause/resume, submit answers, and read the score.
 *   - Owner authorization: a game may only be read/mutated by its owner
 *     (other users -> 403 or 404).
 *   - Per-game serialization of scoring and transactional deduplication: the
 *     UNIQUE (game_id, question_id) constraint prevents a repeat answer from
 *     incrementing the score.
 *   - Answering while paused -> 409. Answering a repeated question -> 409 (or
 *     idempotent 200; this implementation uses 409 for repeat).
 *
 * The service depends on three injectable collaborators so the default
 * `npm test` runs without PostgreSQL, Redis or an identity provider:
 *   - repository:       game persistence (see ./repository.js)
 *   - questionProvider: source of question records for new games
 *   - eventPublisher:   emits score events (see ./events.js, RabbitMQ)
 *   - verifier:         OIDC token verifier (shared src/shared/oidc.js)
 *   - userRepository:   sub -> numeric owner id mapping (user-service contract)
 *
 * All owner authorization is performed against the numeric internal user id
 * derived from the verified OIDC `sub`, matching the user-service's mapping
 * contract (space-fractions.md line 48).
 */

const express = require('express');
const { Client } = require('pg');

const oidc = require('../../../src/shared/oidc');
const { validateAnswer } = require('../../../src/shared/fraction');

const PORT = Number(process.env.GAME_SERVICE_PORT || process.env.PORT || 3001);

/** Ownership/authorization error (other user's game -> 403/404). */
class GameServiceError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'GameServiceError';
    this.status = status;
  }
}

/** Domain state names as stored in the `games.state` column. */
const GAME_STATE = {
  IN_PROGRESS: 'in_progress',
  PAUSED: 'paused',
  FINISHED: 'finished',
};

/**
 * Resolve the numeric owner id from an Authorization header, reusing the
 * user-service mapping contract (sub -> users.id) via an injected repository.
 *
 * @param {object} userRepository { findBySubject }
 * @param {object} verifier       { verify(token): Promise<payload> }
 * @param {string} [authorizationHeader]
 * @returns {Promise<number>} numeric internal user id
 * @throws {oidc.AuthError} missing/invalid credentials -> HTTP 401
 */
async function resolveOwner(userRepository, verifier, authorizationHeader, profile) {
  const token = oidc.bearerToken(authorizationHeader);
  const payload = await verifier.verify(token);
  const sub = payload.sub;
  const existing = await userRepository.findBySubject(sub);
  const user =
    existing ||
    (await userRepository.findOrCreateBySubject(
      sub,
      profile || payload.preferred_username || sub,
    ));
  return user.id;
}

/**
 * Strip `correctAnswer` from question records for player-facing responses.
 * The provider may return full records including correctAnswer (needed for
 * scoring); players must never receive it.
 */
function toPublicQuestion(q) {
  return { id: q.id, prompt: q.prompt, options: Array.isArray(q.options) ? q.options.slice() : [] };
}

/**
 * Build the game-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.repository]         game repository (pg or in-memory)
 * @param {object} [deps.questionProvider]   { list(), get(id) }
 * @param {object} [deps.eventPublisher]     { publishScore(gameId, score) }
 * @param {object} [deps.verifier]           OIDC verifier
 * @param {object} [deps.userRepository]     sub -> id mapping
 * @param {object} [deps.logger]             logger (default console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const repository = deps.repository;
  if (!repository) throw new Error('game-service requires a repository');
  const questionProvider = deps.questionProvider;
  if (!questionProvider) throw new Error('game-service requires a questionProvider');
  const eventPublisher = deps.eventPublisher || { publishScore: async () => {} };
  const verifier =
    deps.verifier ||
    oidc.createTokenVerifier({
      issuer: process.env.OIDC_ISSUER,
      audience: process.env.OIDC_AUDIENCE,
      jwksUri: process.env.OIDC_JWKS_URI,
    });
  const userRepository = deps.userRepository;
  if (!userRepository) throw new Error('game-service requires a userRepository');
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'game-service' });
  });

  // Shared auth helper for route handlers.
  async function requireOwner(req, res) {
    try {
      return await resolveOwner(userRepository, verifier, req.headers.authorization);
    } catch (err) {
      if (err && err.name === 'AuthError') {
        res.status(401).json({ error: 'unauthorized' });
        return null;
      }
      log.error('auth failed', err.message);
      res.status(500).json({ error: 'internal_error' });
      return null;
    }
  }

  /**
   * POST /api/games?questionIds=1,2,3
   *   body { questionIds?: number[] }   (reproducible practice)
   *   201 { id, questions:[{id,prompt,options}] }
   * The correctAnswer is never returned to the player.
   */
  app.post('/api/games', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    try {
      const requested = Array.isArray(req.body && req.body.questionIds)
        ? req.body.questionIds
        : null;

      let questions;
      if (requested && requested.length > 0) {
        questions = [];
        for (const qid of requested) {
          if (!Number.isInteger(qid) || qid <= 0) {
            return res.status(400).json({ error: 'invalid_question_id' });
          }
          const q = await questionProvider.get(qid);
          if (!q) return res.status(404).json({ error: 'question_not_found' });
          questions.push(q);
        }
      } else {
        questions = await questionProvider.list();
        // Stable order is guaranteed by the position column in the persistence
        // layer; the in-memory provider returns insertion order.
        if (!questions.length) {
          return res.status(404).json({ error: 'no_questions_available' });
        }
      }

      const game = await repository.create(ownerId, questions);
      await eventPublisher
        .publishScore(game.id, game.score)
        .catch((err) => log.warn('publishScore failed (non-fatal)', err.message));

      return res.status(201).json({
        id: game.id,
        state: GAME_STATE.IN_PROGRESS,
        questions: questions.map(toPublicQuestion),
      });
    } catch (err) {
      log.error('create game failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games -> 200 { games:[{id,state,score,questions}] } for the
   * authenticated owner, most recent first. Never includes correctAnswer. The
   * browser uses this to recover an in-flight game after a full page reload so
   * the score always comes from persisted PostgreSQL state.
   */
  app.get('/api/games', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;
    try {
      const games = await repository.listByOwner(ownerId);
      return res.status(200).json({
        games: games.map((g) => ({
          id: g.id,
          state: g.state,
          score: g.score,
          questions: (g.questions || []).map(toPublicQuestion),
        })),
      });
    } catch (err) {
      log.error('list games failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games/:id -> 200 game state (player view, never correctAnswer).
   * Other user's game -> 404 (do not leak existence).
   */
  app.get('/api/games/:id', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      return res.status(200).json({
        id: game.id,
        state: game.state,
        score: game.score,
        questions: (game.questions || []).map(toPublicQuestion),
      });
    } catch (err) {
      log.error('get game failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  // Shared pause/resume mutation helper.
  async function mutateState(req, res, nextState) {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      const updated = await repository.setState(id, nextState);
      return res.status(200).json({ id: updated.id, state: updated.state, score: updated.score });
    } catch (err) {
      log.error('set state failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  }

  app.post('/api/games/:id/pause', (req, res) => mutateState(req, res, GAME_STATE.PAUSED));
  app.post('/api/games/:id/resume', (req, res) => mutateState(req, res, GAME_STATE.IN_PROGRESS));

  /**
   * POST /api/games/:id/answers { questionId, answer }
   *   200 { correct:boolean, score:integer }
   *   400 malformed fraction / invalid payload
   *   409 paused game or repeated question
   * Scoring and dedup happen in one transaction in the repository.
   */
  app.post('/api/games/:id/answers', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    const body = req.body || {};
    const questionId = body.questionId;
    const answer = body.answer;
    if (!Number.isInteger(questionId) || questionId <= 0) {
      return res.status(400).json({ error: 'invalid_question_id' });
    }
    if (typeof answer !== 'string' || answer.trim() === '') {
      return res.status(400).json({ error: 'answer_must_be_string' });
    }

    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      if (game.state === GAME_STATE.PAUSED) {
        return res.status(409).json({ error: 'game_paused' });
      }
      // Validate the submitted answer is a well-formed fraction before scoring.
      const question = await questionProvider.get(questionId);
      if (!question) return res.status(404).json({ error: 'question_not_found' });
      const verdict = validateAnswer(question, answer);
      if (verdict.reason === 'answer_malformed') {
        return res.status(400).json({ error: 'malformed_fraction' });
      }

      // scoreAnswer deduplicates via UNIQUE(game_id, question_id); a repeat
      // throws a DuplicateAnswer error the repository surfaces as 409.
      const result = await repository.scoreAnswer(id, questionId, answer, verdict.correct);
      await eventPublisher
        .publishScore(id, result.score)
        .catch((err) => log.warn('publishScore failed (non-fatal)', err.message));

      return res.status(200).json({ correct: result.correct, score: result.score });
    } catch (err) {
      if (err && err.code === 'DUPLICATE_ANSWER') {
        return res.status(409).json({ error: 'answer_already_recorded' });
      }
      log.error('answer failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * GET /api/games/:id/score -> 200 { score:integer }. Other user -> 404.
   */
  app.get('/api/games/:id/score', async (req, res) => {
    const ownerId = await requireOwner(req, res);
    if (ownerId === null) return;

    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'invalid_id' });
    }
    try {
      const game = await repository.get(id);
      if (!game || game.ownerId !== ownerId) {
        return res.status(404).json({ error: 'not_found' });
      }
      return res.status(200).json({ score: game.score });
    } catch (err) {
      log.error('get score failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

/**
 * Build production dependencies (PostgreSQL repository, question pool provider
 * reading from the question-service's repository, RabbitMQ event publisher).
 * Kept lazy so the HTTP handler factory is importable in tests.
 */
function buildProductionDeps() {
  // Lazy requires keep the module importable without those files present until
  // a production runtime actually boots (test-time uses in-memory adapters).
  const { PgGameRepository } = require('./repository');
  const { RabbitMqEventPublisher } = require('./events');
  const { PgQuestionRepository } = require('../../question-service/src/repository');
  const { PgUserRepository } = require('../../user-service/src/index');

  const repository = new PgGameRepository(process.env.DATABASE_URL);
  const questionProvider = new PgQuestionRepository(process.env.DATABASE_URL);
  const userRepository = new PgUserRepository(process.env.DATABASE_URL);
  const eventPublisher = process.env.RABBITMQ_URL
    ? new RabbitMqEventPublisher(process.env.RABBITMQ_URL)
    : null;
  const verifier = oidc.createTokenVerifier({
    issuer: process.env.OIDC_ISSUER,
    audience: process.env.OIDC_AUDIENCE,
    jwksUri: process.env.OIDC_JWKS_URI,
  });
  return { repository, questionProvider, userRepository, eventPublisher, verifier };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  const deps = buildProductionDeps();
  const app = buildApp(deps);
  const server = app.listen(PORT, () => {
    console.log(`game-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  buildProductionDeps,
  resolveOwner,
  toPublicQuestion,
  GAME_STATE,
  GameServiceError,
};

