};

/** Per-app memoized in-process HTTP servers. */
const invokerCache = new WeakMap();

async function getInvoker(app) {
  let pending = invokerCache.get(app);
  if (!pending) {
    pending = createInvoker(app);
    invokerCache.set(app, pending);
  }
  return pending;
}

function request(app) {
  return {
    async get(path, headers = {}) {
      return (await getInvoker(app)).get(path, headers);
    },
    async post(path, body, headers = {}) {
      return (await getInvoker(app)).post(path, body, headers);
    },
    async delete(path, headers = {}) {
      return (await getInvoker(app)).delete(path, headers);
    },
  };
}

function bearer(sub) {
  return { authorization: `Bearer token-for-${sub}` };
}

function buildAdmin(overrides = {}) {
  const userRepository = new InMemoryUserRepository();
  const verifier = overrides.verifier || makeVerifier({ payload: ADMIN_PAYLOAD });
  const questionRepository = overrides.questionRepository || new InMemoryQuestionRepository();
  const app = buildAdminApp({
    userRepository,
    verifier,
    questionRepository,
    search: overrides.search || { index: async () => {}, remove: async () => {} },
    logger: { error() {}, warn() {} },
  });
  return { app, userRepository, verifier, questionRepository };
}

