'use strict';

/**
 * Shared in-process HTTP helper for Express-route tests.
 *
 * Express 4 middleware (expressInit), res.json() and res.send() all require a
 * real Node http.ServerResponse (setHeader/getHeader/end/...). Hand-rolled
 * mock response objects are brittle, so this module instead binds the Express
 * app to a real ephemeral HTTP server (port 0) and performs an actual in-process
 * request/response round trip via node:http. No external services are required,
 * so the default `npm test` runs without PostgreSQL, Redis, RabbitMQ,
 * Elasticsearch or a live identity provider.
 */

const http = require('node:http');

/**
 * Build a request helper bound to an Express app via a real ephemeral server.
 *
 * @param {import('express').Express} app
 * @returns {{ post(url, body, headers), get(url, headers), delete(url, headers), close() }}
 */
function createInvoker(app) {
  const server = http.createServer(app);

  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => {
      // Unref the ephemeral listener so open test servers never keep the Node
      // process (and therefore `node --test`) alive after the suite finishes.
      server.unref();
      const address = server.address();
      const base = `http://127.0.0.1:${address.port}`;

      function request(method, path, body, headers = {}) {
        return new Promise((res, rej) => {
          const payload = body === undefined || body === null ? null : JSON.stringify(body);
          const req = http.request(
            {
              host: '127.0.0.1',
              port: address.port,
              method,
              path,
              headers: Object.assign(
                payload === null
                  ? {}
                  : { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) },
                headers,
              ),
            },
            (response) => {
              const chunks = [];
              response.on('data', (c) => chunks.push(c));
              response.on('end', () => {
                const text = Buffer.concat(chunks).toString('utf8');
                let body = undefined;
                if (text) {
                  try {
                    body = JSON.parse(text);
                  } catch {
                    body = text;
                  }
                }
                res({ status: response.statusCode, body });
              });
            },
          );
          req.on('error', rej);
          if (payload !== null) req.write(payload);
          req.end();
        });
      }

      const invoker = {
        post: (path, body, headers) => request('POST', path, body, headers),
        get: (path, headers) => request('GET', path, undefined, headers),
        delete: (path, headers) => request('DELETE', path, undefined, headers),
        close: () =>
          new Promise((res) => {
            server.close(() => res());
          }),
      };

      // Keep the base around for optional debugging.
      invoker.base = base;
      resolve(invoker);
    });
  });
}

module.exports = { createInvoker };

'use strict';

/**
 * Admin service — authenticated administrator question CRUD for Space Fractions.
 *
 * Responsibilities (space-fractions.md lines 15-16; Architecture_View.md
 * lines 3-14 — the "Update Questions" admin use case):
 *   - Authenticate a Bearer OIDC access token and authorize the ADMIN role.
 *   - POST   /api/admin/questions     -> 201 {id,prompt,options,correctAnswer}
 *   - GET    /api/admin/questions     -> 200 {questions:[...]}
 *   - DELETE /api/admin/questions/:id -> 200 (or 204), 404 when id missing.
 *   - Normal (non-admin) users receive 403; missing/invalid credentials 401.
 *
 * The admin service is the authorization boundary. It reuses:
 *   - `src/shared/oidc.js`            for token verification and admin-role check.
 *   - `packages/user-service`         `authenticate()` to map verified `sub` to a
 *     numeric internal user id (single home for JWT sub -> users.id resolution).
 *   - `packages/question-service`      `validateQuestionPayload()` + repository +
 *     `QuestionSearch` so question writes and search indexing stay consistent
 *     with the question service (correctAnswer validated as a single exact
 *     fraction; options array of strings).
 *
 * OIDC environment contract (space-fractions.md line 40):
 *   - OIDC_ISSUER/OIDC_AUDIENCE/OIDC_JWKS_URI/OIDC_ADMIN_ROLE (default "admin").
 *
 * Like the question/user services, the pg `Client` connects lazily so the HTTP
 * listener still boots when PostgreSQL is temporarily unreachable. Unit tests
 * inject in-memory repositories and a scripted token verifier.
 */

const express = require('express');

const oidc = require('../../../src/shared/oidc');
const {
  validateQuestionPayload,
  ValidationError: QuestionValidationError,
} = require('../../question-service/src/index');
const {
  InMemoryQuestionRepository,
  PgQuestionRepository,
} = require('../../question-service/src/repository');
const { QuestionSearch } = require('../../question-service/src/search');
const {
  authenticate,
  InMemoryUserRepository,
  PgUserRepository,
} = require('../../user-service/src/index');

const PORT = Number(process.env.ADMIN_SERVICE_PORT || process.env.PORT || 3004);
const ADMIN_ROLE = () => process.env.OIDC_ADMIN_ROLE || 'admin';

/**
 * Build the admin-service Express app.
 *
 * @param {object} [deps]
 * @param {object} [deps.userRepository]  user repository (pg or in-memory)
 * @param {object} [deps.verifier]        OIDC token verifier ({ verify })
 * @param {object} [deps.questionRepository] question repository (pg or in-memory)
 * @param {object} [deps.search]          QuestionSearch adapter
 * @param {object} [deps.logger]          logger (default console)
 * @returns {import('express').Express}
 */
function buildApp(deps = {}) {
  const userRepository = deps.userRepository || new InMemoryUserRepository();
  const verifier =
    deps.verifier ||
    oidc.createTokenVerifier({
      issuer: process.env.OIDC_ISSUER,
      audience: process.env.OIDC_AUDIENCE,
      jwksUri: process.env.OIDC_JWKS_URI,
    });
  const questionRepository =
    deps.questionRepository || new InMemoryQuestionRepository();
  const search = deps.search || new QuestionSearch(null);
  const log = deps.logger || console;

  const app = express();
  app.use(express.json({ limit: '1mb' }));

  // Health for orchestration/tests.
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok', service: 'admin-service' });
  });

  /**
   * Resolve the authenticated principal and enforce the administrator role.
   * Throws UserServiceError for JSON-error mapping is avoided here; instead we
   * branch inside handlers via the thrown error's `name`/`status`. `authenticate`
   * throws a shared oidc.AuthError (401) on missing/invalid credentials.
   *
   * Returns { id, subject, profile, roles } for an admin, otherwise throws a
   * 403 error object we construct locally.
   */
  async function requireAdmin(req) {
    const principal = await authenticate(
      userRepository,
      verifier,
      req.headers.authorization,
    );
    if (!oidc.isAdmin({ realm_access: { roles: principal.roles } }, ADMIN_ROLE())) {
      const err = new Error('forbidden');
      err.name = 'ForbiddenError';
      err.status = 403;
      throw err;
    }
    return principal;
  }

  /**
   * List all questions (admin view). Contract: { questions: [...] }.
   *   200 on success; 401 missing/invalid credentials; 403 non-admin.
   */
  app.get('/api/admin/questions', async (req, res) => {
    try {
      await requireAdmin(req);
      const questions = await questionRepository.list();
      res.status(200).json({ questions });
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      if (err && err.name === 'ForbiddenError') {
        return res.status(403).json({ error: 'forbidden' });
      }
      log.error('list admin questions failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Create a question. Contract: 201 {id,prompt,options,correctAnswer}.
   * Malformed payload (bad prompt/options/fraction) -> 400; 401/403 as above.
   */
  app.post('/api/admin/questions', async (req, res) => {
    try {
      await requireAdmin(req);
      const normalized = validateQuestionPayload(req.body);
      const created = await questionRepository.create(normalized);
      await search.index(created).catch((indexErr) => {
        // Search indexing is best-effort; PostgreSQL remains the source of truth.
        log.warn('search index failed (non-fatal)', indexErr.message);
      });
      res.status(201).json(created);
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      if (err && err.name === 'ForbiddenError') {
        return res.status(403).json({ error: 'forbidden' });
      }
      if (err instanceof QuestionValidationError) {
        return res.status(400).json({ error: err.message });
      }
      log.error('create admin question failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  /**
   * Delete a question by id. Contract: 200 (JSON ack) or 204 on success, 404 when
   * the id does not exist, 400 on a malformed id, 401/403 as above.
   */
  app.delete('/api/admin/questions/:id', async (req, res) => {
    try {
      await requireAdmin(req);
      const id = Number(req.params.id);
      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ error: 'invalid_id' });
      }
      const removed = await questionRepository.remove(id);
      if (!removed) return res.status(404).json({ error: 'not_found' });
      await search.remove(id).catch((removeErr) =>
        log.warn('search remove failed (non-fatal)', removeErr.message),
      );
      return res.status(200).json({ deleted: id });
    } catch (err) {
      if (err && err.name === 'AuthError') {
        return res.status(401).json({ error: 'unauthorized' });
      }
      if (err && err.name === 'ForbiddenError') {
        return res.status(403).json({ error: 'forbidden' });
      }
      log.error('delete admin question failed', err.message);
      return res.status(500).json({ error: 'internal_error' });
    }
  });

  return app;
}

/**
 * Build production dependencies: PostgreSQL-backed user + question repositories,
 * a real OIDC verifier, and an Elasticsearch-backed QuestionSearch when
 * ELASTICSEARCH_URL is configured.
 */
function buildProductionDeps() {
  const userRepository = new PgUserRepository(process.env.DATABASE_URL);
  const questionRepository = new PgQuestionRepository(process.env.DATABASE_URL);
  const verifier = oidc.createTokenVerifier({
    issuer: process.env.OIDC_ISSUER,
    audience: process.env.OIDC_AUDIENCE,
    jwksUri: process.env.OIDC_JWKS_URI,
  });
  const { Client } = require('@elastic/elasticsearch');
  const search = process.env.ELASTICSEARCH_URL
    ? new QuestionSearch(new Client({ node: process.env.ELASTICSEARCH_URL }))
    : new QuestionSearch(null);
  return { userRepository, questionRepository, verifier, search };
}

// Direct execution only (not on import, so tests can require buildApp).
if (require.main === module) {
  const { userRepository, questionRepository, verifier, search } = buildProductionDeps();
  const app = buildApp({ userRepository, questionRepository, verifier, search });
  const server = app.listen(PORT, () => {
    console.log(`admin-service listening on :${PORT}`);
  });

  const shutdown = () => {
    server.close(() => process.exit(0));
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

module.exports = {
  buildApp,
  buildProductionDeps,
};

'use strict';

/**
 * Space Fractions browser UI (plain JS, no bundler).
 *
 * The gateway serves this file as a static asset. All API calls go through the
 * same origin (the gateway) and carry the OIDC access token in a Bearer
 * header. The token is obtained via the authorization-code + PKCE (S256) flow
 * documented below. Player responses never expose `correctAnswer` — the UI
 * only reads `correct` (boolean) and `score` (integer).
 *
 * Views are simple <section> elements toggled by a `show(view)` helper; the
 * game state (id/questions/index/score/paused) is kept in `game`.
 */

(function () {
  'use strict';

  // ---------------------------------------------------------------------
  // OIDC configuration (derived from gateway env via a small /config.json
  // if present, otherwise sensible local-only defaults). Real deployments
  // set PUBLIC_ORIGIN and OIDC_ISSUER; the gateway exposes these to the
  // browser through a static config file so redirects never hard-code a
  // host:port (test runtimes remap ports).
  // ---------------------------------------------------------------------
  const CONFIG = window.SPACE_FRACTIONS_CONFIG || {};

  const ISSUER = CONFIG.issuer || 'http://localhost:8080/realms/space-fractions';
  const CLIENT_ID = CONFIG.clientId || 'space-fractions-client';
  const REDIRECT_URI =
    CONFIG.redirectUri || `${window.location.origin}/`;
  const SCOPE = CONFIG.scope || 'openid profile';

  // Token storage. `accessToken` is acquired at sign-in via PKCE.
  let accessToken = sessionStorage.getItem('space-fractions.access_token') || null;
  let idToken = sessionStorage.getItem('space-fractions.id_token') || null;
  let profile = null;

  // Active game state (never includes correctAnswer).
  let game = {
    id: null,
    questions: [],
    current: 0,
    score: 0,
    paused: false,
    answered: new Set(), // question ids already answered
  };

  // ---------------------------------------------------------------------
  // Small DOM helpers
  // ---------------------------------------------------------------------
  const $ = (sel) => document.querySelector(sel);

  function show(viewId) {
    document.querySelectorAll('.view').forEach((v) => (v.hidden = v.id !== viewId));
  }

  function setAuthUI() {
    const loggedIn = !!accessToken && !!profile;
    $('#login-btn').hidden = loggedIn;
    $('#logout-btn').hidden = !loggedIn;
    $('#user-name').hidden = !loggedIn;
    if (loggedIn && profile) {
      $('#user-name').textContent = profile.preferred_username || profile.name || profile.sub || 'user';
    }
  }

  function clearFeedback() {
    const fb = $('#answer-feedback');
    fb.hidden = true;
    fb.textContent = '';
  }

  function setFeedback(text, ok) {
    const fb = $('#answer-feedback');
    fb.hidden = false;
    fb.textContent = text;
    fb.className = `feedback ${ok ? 'correct' : 'incorrect'}`;
  }

  // ---------------------------------------------------------------------
  // Auth: authorization-code + PKCE (S256)
  // ---------------------------------------------------------------------
  function base64url(buf) {
    if (typeof buf === 'string') buf = new TextEncoder().encode(buf);
    let str = '';
    const bytes = new Uint8Array(buf);
    const CHUNK = 0x8000;
    for (let i = 0; i < bytes.length; i += CHUNK) {
      str += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
    }
    return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }

  function randomString(len) {
    const arr = new Uint8Array(len);
    crypto.getRandomValues(arr);
    return base64url(arr);
  }

  async function sha256(str) {
    return crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
  }

  async function buildAuthorizeUrl() {
    const verifier = randomString(64);
    const challenge = base64url(await sha256(verifier));
    sessionStorage.setItem('space-fractions.pkce_verifier', verifier);
    const state = randomString(32);
    sessionStorage.setItem('space-fractions.oauth_state', state);

    const params = new URLSearchParams({
      response_type: 'code',
      client_id: CLIENT_ID,
      redirect_uri: REDIRECT_URI,
      scope: SCOPE,
      state,
      code_challenge: challenge,
      code_challenge_method: 'S256',
    });
    return `${ISSUER.replace(/\/$/, '')}/protocol/openid-connect/auth?${params.toString()}`;
  }

  function decodeJwtPayload(token) {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    try {
      const payload = parts[1].replace(/-/g, '+').replace(/_/g, '/');
      const padded = payload + '='.repeat((4 - (payload.length % 4)) % 4);
      return JSON.parse(atob(padded));
    } catch {
      return null;
    }
  }

  async function exchangeCode(code) {
    const verifier = sessionStorage.getItem('space-fractions.pkce_verifier');
    const tokenUrl = `${ISSUER.replace(/\/$/, '')}/protocol/openid-connect/token`;
    const body = new URLSearchParams({
      grant_type: 'authorization_code',
      code,
      redirect_uri: REDIRECT_URI,
      client_id: CLIENT_ID,
      code_verifier: verifier,
    });
    const res = await fetch(tokenUrl, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: body.toString(),
    });
    if (!res.ok) throw new Error('token exchange failed');
    const data = await res.json();
    accessToken = data.access_token;
    idToken = data.id_token || null;
    sessionStorage.setItem('space-fractions.access_token', accessToken);
    if (idToken) sessionStorage.setItem('space-fractions.id_token', idToken);
    profile = idToken ? decodeJwtPayload(idToken) : (accessToken ? decodeJwtPayload(accessToken) : null);
  }

  async function handleRedirect() {
    const params = new URLSearchParams(window.location.search);
    const code = params.get('code');
    const state = params.get('state');
    const storedState = sessionStorage.getItem('space-fractions.oauth_state');
    if (!code) return false;
    if (!storedState || state !== storedState) {
      console.error('OAuth state mismatch');
      return false;
    }
    await exchangeCode(code);
    sessionStorage.removeItem('space-fractions.pkce_verifier');
    sessionStorage.removeItem('space-fractions.oauth_state');
    window.history.replaceState({}, document.title, REDIRECT_URI);
    setAuthUI();
    return true;
  }

  async function signIn() {
    window.location.assign(await buildAuthorizeUrl());
  }

  function signOut() {
    accessToken = null;
    idToken = null;
    profile = null;
    sessionStorage.removeItem('space-fractions.access_token');
    sessionStorage.removeItem('space-fractions.id_token');
    sessionStorage.removeItem('space-fractions.game_id');
    resetGame();
    show('view-intro');
    setAuthUI();
  }

  // ---------------------------------------------------------------------
  // API helper (adds Bearer token; maps status to typed errors)
  // ---------------------------------------------------------------------
  async function api(method, url, body) {
    const headers = { accept: 'application/json' };
    if (accessToken) headers.authorization = `Bearer ${accessToken}`;
    let payload;
    if (body !== undefined) {
      headers['content-type'] = 'application/json';
      payload = JSON.stringify(body);
    }
    const res = await fetch(url, { method, headers, body: payload });
    let data = null;
    const text = await res.text();
    if (text) {
      try {
        data = JSON.parse(text);
      } catch {
        data = { raw: text };
      }
    }
    if (!res.ok) {
      const err = new Error(data && data.error ? data.error : `HTTP ${res.status}`);
      err.status = res.status;
      err.data = data;
      throw err;
    }
    return data;
  }

  function handleApiError(err) {
    if (err.status === 401) {
      setFeedback('Please sign in to continue.', false);
      show('view-intro');
      setAuthUI();
      return;
    }
    setFeedback(err.message || 'Something went wrong.', false);
  }

  // ---------------------------------------------------------------------
  // Game flow
  // ---------------------------------------------------------------------
  function resetGame() {
    game = {
      id: null,
      questions: [],
      current: 0,
      score: 0,
      paused: false,
